    and app_type = #{searchCriteria.type,jdbcType=VARCHAR}


    and resource_type = #{searchCriteria.source,jdbcType=VARCHAR}


    and workflow_type = #{searchCriteria.workflowType,jdbcType=VARCHAR}

order by published_on desc

